import React, { useState } from "react";
import { useDispatch } from "react-redux";
import { useNavigate } from "react-router-dom";
import { signupSuccess } from "./AuthSlice";

// Import your local asset file here as well

const Signup = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [clientError, setClientError] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    setClientError("");

    if (!email.includes("@")) {
      setClientError("Please enter a valid email address.");
      return;
    }
    if (password.length < 5) {
      setClientError("Password must be at least 5 characters long.");
      return;
    }
    if (password !== confirmPassword) {
      setClientError("Passwords do not match.");
      return;
    }

    const fakeUserPayload = {
      email,
      username: username || email.split("@")[0],
      // Assign the local image
    };

    dispatch(signupSuccess(fakeUserPayload));
    navigate("/");
  };

  return (
    <div className="w-screen h-screen flex flex-col items-center justify-center bg-[#09090b] text-white px-4">
      <div className="w-full max-w-md bg-[#121214] border border-zinc-900 p-8 rounded-xl shadow-2xl space-y-6">
        <div className="text-center space-y-2">
          <div className="text-2xl font-black tracking-tighter text-white">
            SPOTIFY<span className="text-[#ff2a74]">PINK</span>
          </div>
          <h2 className="text-xl font-bold text-zinc-100">
            Sign up for free to start listening.
          </h2>
        </div>

        {clientError && (
          <div className="p-3 bg-red-950/40 border border-red-900/60 text-red-400 text-xs rounded text-center font-medium">
            {clientError}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-xs font-bold uppercase text-zinc-400 mb-1.5">
              What should we call you?
            </label>
            <input
              type="text"
              placeholder="Enter a profile name."
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full bg-zinc-900 border border-zinc-800 text-white text-sm p-3 rounded focus:outline-none focus:border-[#ff2a74] transition"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-bold uppercase text-zinc-400 mb-1.5">
              What is your email?
            </label>
            <input
              type="email"
              placeholder="name@domain.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-zinc-900 border border-zinc-800 text-white text-sm p-3 rounded focus:outline-none focus:border-[#ff2a74] transition"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-bold uppercase text-zinc-400 mb-1.5">
              Create a password
            </label>
            <input
              type="password"
              placeholder="Minimum 5 characters"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-zinc-900 border border-zinc-800 text-white text-sm p-3 rounded focus:outline-none focus:border-[#ff2a74] transition"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-bold uppercase text-zinc-400 mb-1.5">
              Confirm your password
            </label>
            <input
              type="password"
              placeholder="Enter password again"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="w-full bg-zinc-900 border border-zinc-800 text-white text-sm p-3 rounded focus:outline-none focus:border-[#ff2a74] transition"
              required
            />
          </div>

          <button
            type="submit"
            className="w-full py-3 bg-[#ff2a74] hover:bg-pink-700 text-white font-bold text-sm rounded-full tracking-wide shadow-md transform active:scale-95 transition mt-2"
          >
            Sign Up
          </button>
        </form>

        <div className="border-t border-zinc-800/80 pt-4 text-center">
          <p className="text-xs text-zinc-400">
            Already have an account?{" "}
            <span
              onClick={() => navigate("/login")}
              className="text-[#ff2a74] hover:underline cursor-pointer font-semibold"
            >
              Log in here
            </span>
          </p>
        </div>
      </div>
    </div>
  );
};

export default Signup;
